def describe(code):
    if 200 <= code < 300:
        return 'success'
    if 300 <= code < 400:
        return 'redirection'
    if 400 <= code < 500:
        return 'client error'
    if 500 <= code < 600:
        return 'server error'
    return 'unknown'

def status_report(log_lines):
    counts = {}
    for line in log_lines:
        code = int(line.split()[-1])
        key = f'{code // 100}xx'
        counts[key] = counts.get(key, 0) + 1
    return counts

