def handle(store, method, key, value=None):
    if method == 'GET':
        if key in store:
            return 200, store[key]
        return 404, None
    if method == 'POST':
        store[key] = value
        return 201
    if method == 'PUT':
        if key not in store:
            return 404
        store[key] = value
        return 200
    if method == 'DELETE':
        if key not in store:
            return 404
        del store[key]
        return 204
    return 405

